    int phy_id;

    n = sysconf(_SC_NPROCESSORS_ONLN);

	if (core < 0 || core >= (int) n) {
		errno = -EINVAL;
		return -1;
	}

	if((cmask = CPU_ALLOC(n)) == NULL)
		perror("CPU ALLOC");

	CPU_ZERO_S(n, cmask);
	CPU_SET_S(core, n, cmask);

	ret = sched_setaffinity(0, n, cmask);
	CPU_FREE(cmask);

    /* TODO: Setting NUMA nodes 
     * Occasionally dies */
    /*
