/* start asnchronous non-blocking connection */

static void start_connect(struct connection * c)
{
	apr_status_t rv;

    int sock_fd;

    if (!(_started < _requests))
    	return;

    c->read = 0;
    c->bread = 0;
    c->keepalive = 0;
    c->keepalive_cnt = 0;
    c->cbx = 0;
    c->gotheader = 0;
    c->rwrite = 0;

    if (c->ctx)
        apr_pool_clear(c->ctx);
    else
        apr_pool_create(&c->ctx, cntxt);

    if ((rv = apr_socket_create(&c->aprsock, _destsa->family,
                SOCK_STREAM, 0, c->ctx)) != APR_SUCCESS) {
    	apr_err("socket", rv);
    }

#ifndef HAVE_MTCP
	if (windowsize != 0) {
        rv = apr_socket_opt_set(c->aprsock, APR_SO_SNDBUF, 
                                windowsize);
        if (rv != APR_SUCCESS && rv != APR_ENOTIMPL) {
            apr_err("socket send buffer", rv);
        }
        rv = apr_socket_opt_set(c->aprsock, APR_SO_RCVBUF, 
                                windowsize);
        if (rv != APR_SUCCESS && rv != APR_ENOTIMPL) {
            apr_err("socket receive buffer", rv);
        }
    }
#endif

	if ((rv = apr_socket_opt_set(c->aprsock, APR_SO_NONBLOCK, 1))
         != APR_SUCCESS) {
		apr_err("socket nonblock", rv);
    }

    c->start = _lasttime = apr_time_now();
#ifdef USE_SSL
    if (is_ssl) {
        BIO *bio;
        apr_os_sock_t fd;
        if ((c->ssl = SSL_new(ssl_ctx)) == NULL) {
            BIO_printf(bio_err, "SSL_new failed.\n");
            ERR_print_errors(bio_err);
            exit(1);
        }
        ssl_rand_seed();
        apr_os_sock_get(&fd, c->aprsock);
        bio = BIO_new_socket(fd, BIO_NOCLOSE);
        SSL_set_bio(c->ssl, bio, bio);
        SSL_set_connect_state(c->ssl);
		if (verbosity >= 4) {
            BIO_set_callback(bio, ssl_print_cb);
            BIO_set_callback_arg(bio, (void *)bio_err);
        }
    } else {
        c->ssl = NULL;
    }
#endif
    if ((rv = apr_socket_connect(c->aprsock, _destsa)) != APR_SUCCESS) {
		if (APR_STATUS_IS_EINPROGRESS(rv)) {
			apr_pollfd_t new_pollfd;
            c->state = STATE_CONNECTING;
            c->rwrite = 0;
            new_pollfd.desc_type = APR_POLL_SOCKET;
            new_pollfd.reqevents = APR_POLLOUT;
            new_pollfd.desc.s = c->aprsock;
            new_pollfd.client_data = c;
            apr_pollset_add(readbits, &new_pollfd);
            return;
        }
        else {
            apr_pollfd_t remove_pollfd;
            remove_pollfd.desc_type = APR_POLL_SOCKET;
            remove_pollfd.desc.s = c->aprsock;
            apr_pollset_remove(readbits, &remove_pollfd);
            apr_socket_close(c->aprsock);
            if (bad > 100) {
                fprintf(stderr,
                   "\nTest aborted after 100 failures\n\n");
                apr_err("apr_socket_connect()", rv);
            }
			pthread_mutex_lock(&err_mutex);
			err_conn++;
			bad++;
			pthread_mutex_unlock(&err_mutex);
			c->state = STATE_UNCONNECTED;
            start_connect(c);
            return;
        }
    }

    /* connected first time */
    c->state = STATE_CONNECTED;
    _started++;

#ifdef USE_SSL
    if (c->ssl) {
        ssl_proceed_handshake(c);
    } else
#endif
    {
		write_request(c);
    }
}

/* --------------------------------------------------------- */

/* close down connection and save stats */

static void close_connection(struct connection * c)
{
    int i;


    int sock_fd;
    apr_os_sock_get(&sock_fd, c->aprsock);

    c->keepalive_cnt = 0;
    if (c->read == 0 && c->keepalive) {
        /*
         * server has legitimately shut down an idle keep alive request
         */
        if (_good)
            _good--;     /* connection never happened */
    }
    else {
        if (_good == 1) {
            /* first time here */
            _doclen = c->bread;
        }
        else if (c->bread != _doclen) {
			pthread_mutex_lock(&err_mutex);
			bad++;
            err_length++;
			pthread_mutex_unlock(&err_mutex);
        }
        /* save out time */
        if (_done < _requests) {
            struct data *s = &_stats[_done];
			_done++;
            c->done      = _lasttime = apr_time_now();
            s->starttime = c->start;
            s->ctime     = ap_max(0, c->connect - c->start);
            s->time      = ap_max(0, c->done - c->start);
            s->waittime  = ap_max(0, c->beginread - c->endwrite);

			if (heartbeatres && !(_done % heartbeatres)) {
               	fprintf(stderr, "CPU%d: Completed %d requests\n", _cpu, _done);
               	fflush(stderr);
           	}	
		}
    }

    {
        apr_pollfd_t remove_pollfd;
        remove_pollfd.desc_type = APR_POLL_SOCKET;
        remove_pollfd.desc.s = c->aprsock;
		apr_pollset_remove(readbits, &remove_pollfd);
#ifdef USE_SSL
        if (c->ssl) {
            SSL_shutdown(c->ssl);
            SSL_free(c->ssl);
            c->ssl = NULL;
        }
#endif
        apr_socket_close(c->aprsock);
    }
    c->state = STATE_UNCONNECTED;

    /* connect again */
    start_connect(c);
    return;
}

/* --------------------------------------------------------- */

/* read data from connection */

static void read_connection(struct connection * c)
{
    apr_size_t r;
    apr_status_t status;
    char *part;
    char respcode[4];       /* 3 digits and null */

    r = sizeof(buffer);

#ifdef USE_SSL
    if (c->ssl) {
        status = SSL_read(c->ssl, buffer, r);
        if (status <= 0) {
            int scode = SSL_get_error(c->ssl, status);

            if (scode == SSL_ERROR_ZERO_RETURN) {
                /* connection closed cleanly: */
                _good++;
                close_connection(c);
            }
            else if (scode != SSL_ERROR_WANT_WRITE
                     && scode != SSL_ERROR_WANT_READ) {
                /* some fatal error: */
                c->read = 0;
                BIO_printf(bio_err, "SSL read failed - closing connection\n");
                ERR_print_errors(bio_err);
                close_connection(c);
            }
            return;
        }
        r = status;
    }
    else
#endif
    {
        status = apr_socket_recv(c->aprsock, buffer, &r);
        if (APR_STATUS_IS_EAGAIN(status))
            return;
        else if (r == 0 && APR_STATUS_IS_EOF(status)) {
            _good++;
            close_connection(c);
            return;
        }
        /* catch legitimate fatal apr_socket_recv errors */
        else if (status != APR_SUCCESS) {
			pthread_mutex_lock(&err_mutex);
			err_recv++;
			pthread_mutex_unlock(&err_mutex);
            if (recverrok) {
                pthread_mutex_lock(&err_mutex);
				bad++;
				pthread_mutex_unlock(&err_mutex);
                close_connection(c);
                if (verbosity >= 1) {
                    char buf[120];
                    fprintf(stderr,"%s: %s (%d)\n", "apr_socket_recv", apr_strerror(status, buf, sizeof buf), status);
                }
                return;
            } else {
                apr_err("apr_socket_recv", status);
            }
        }
    }

	_totalread += r;
    if (c->read == 0) {
        c->beginread = apr_time_now();
    }
    c->read += r;


    if (!c->gotheader) {
        char *s;
        int l = 4;
        apr_size_t space = CBUFFSIZE - c->cbx - 1; /* -1 allows for \0 term */
        int tocopy = (space < r) ? space : r;
#ifdef NOT_ASCII
        apr_size_t inbytes_left = space, outbytes_left = space;

        status = apr_xlate_conv_buffer(from_ascii, buffer, &inbytes_left,
                           c->cbuff + c->cbx, &outbytes_left);
        if (status || inbytes_left || outbytes_left) {
            fprintf(stderr, "only simple translation is supported (%d/%" APR_SIZE_T_FMT
                            "/%" APR_SIZE_T_FMT ")\n", status, inbytes_left, outbytes_left);
            exit(1);
        }
#else
        memcpy(c->cbuff + c->cbx, buffer, space);
#endif              /* NOT_ASCII */
        c->cbx += tocopy;
        space -= tocopy;
        c->cbuff[c->cbx] = 0;   /* terminate for benefit of strstr */
        if (verbosity >= 2) {
            printf("LOG: header received:\n%s\n", c->cbuff);
        }
        s = strstr(c->cbuff, "\r\n\r\n");
        /*
         * this next line is so that we talk to NCSA 1.5 which blatantly
         * breaks the http specifaction
         */
        if (!s) {
            s = strstr(c->cbuff, "\n\n");
            l = 2;
        }

        if (!s) {
            /* read rest next time */
            if (space) {
                return;
            }
            else {
            /* header is in invalid or too big - close connection */
                apr_pollfd_t remove_pollfd;
                remove_pollfd.desc_type = APR_POLL_SOCKET;
                remove_pollfd.desc.s = c->aprsock;
                apr_pollset_remove(readbits, &remove_pollfd);
                apr_socket_close(c->aprsock);
                if (bad > 100) {
                    err("\nTest aborted after 100 failures\n\n");
                }
				printf("%d trying to acquire err_mutex\n", _cpu);
				pthread_mutex_lock(&err_mutex);
				err_response++;
				bad++;
				pthread_mutex_unlock(&err_mutex);
				start_connect(c);
            }
        }
        else {
            /* have full header */
            if (!_good) {
                /*
                 * this is first time, extract some interesting info
                 */
                char *p, *q;
                p = strstr(c->cbuff, "Server:");
                q = servername;
                if (p) {
                    p += 8;
                    while (*p > 32)
                    *q++ = *p++;
                }
                *q = 0;
            }
            /*
             * XXX: this parsing isn't even remotely HTTP compliant... but in
             * the interest of speed it doesn't totally have to be, it just
             * needs to be extended to handle whatever servers folks want to
             * test against. -djg
             */

            /* check response code */
            part = strstr(c->cbuff, "HTTP");    /* really HTTP/1.x_ */
            if (part && strlen(part) > strlen("HTTP/1.x_")) {
                strncpy(respcode, (part + strlen("HTTP/1.x_")), 3);
                respcode[3] = '\0';
            }
            else {
                strcpy(respcode, "500");
            }

            if (respcode[0] != '2') {
				pthread_mutex_lock(&err_mutex);
				err_response++;
				pthread_mutex_unlock(&err_mutex);
                if (verbosity >= 2)
                    printf("WARNING: Response code not 2xx (%s)\n", respcode);
            }
            else if (verbosity >= 3) {
                printf("LOG: Response code = %s\n", respcode);
            }
            c->gotheader = 1;
            *s = 0;     /* terminate at end of header */
            if (keepalive &&
            (strstr(c->cbuff, "Keep-Alive")
             || strstr(c->cbuff, "keep-alive"))) {  /* for benefit of MSIIS */
                char *cl;
                cl = strstr(c->cbuff, "Content-Length:");
                /* handle NCSA, which sends Content-length: */
                if (!cl)
                    cl = strstr(c->cbuff, "Content-length:");
                if (cl) {
                    c->keepalive = 1;
                    /* response to HEAD doesn't have entity body */
                    c->length = posting >= 0 ? atoi(cl + 16) : 0;
                }
                /* The response may not have a Content-Length header */
                if (!cl) {
                    c->keepalive = 1;
                    c->length = 0; 
                }
            }
            c->bread += c->cbx - (s + l - c->cbuff) + r - tocopy;
			_totalbread += c->bread;
        }
    }
    else {
        /* outside header, everything we have read is entity body */
        c->bread += r;
		_totalbread += r;
    }

    if (c->keepalive && (c->bread >= c->length)) {
        /* finished a keep-alive connection */
        _good++;
        /* save out time */
        if (_good == 1) {
            /* first time here */
            _doclen = c->bread;
        }
        else if (c->bread != _doclen) {
			pthread_mutex_lock(&err_mutex);
			bad++;
            err_length++;
			pthread_mutex_unlock(&err_mutex);
        }
        if (_done < _requests) {
			struct data *s = &_stats[_done];
			_done++;
			_doneka++;
            c->done      = apr_time_now();
            s->starttime = c->start;
            s->ctime     = ap_max(0, c->connect - c->start);
            s->time      = ap_max(0, c->done - c->start);
            s->waittime  = ap_max(0, c->beginread - c->endwrite);

			if (heartbeatres && !(_done % heartbeatres)) {
                fprintf(stderr, "CPU%d:Completed %d requests\n", _cpu, _done);
                fflush(stderr);
            }
        }

        if(keepalive_cnt > 0){
            c->keepalive_cnt++;
            int sock_fd;
            apr_os_sock_get(&sock_fd, c->aprsock);
            /*printf("CPU%d-Socket%d: %d/%d\n", _cpu, sock_fd, c->keepalive_cnt, keepalive_cnt);*/
            if(c->keepalive_cnt >= keepalive_cnt){
                c->keepalive = 0;
                close_connection(c);
                return;
            }
        } 

        c->keepalive = 0;
        c->length = 0;
        c->gotheader = 0;
        c->cbx = 0;
        c->read = c->bread = 0;
        /* zero connect time with keep-alive */
        c->start = c->connect = _lasttime = apr_time_now();
        write_request(c);

    }
}

/* ------------------------------------------------------- */

/* Thread setup and cleanup functions */


#ifdef USE_SSL
void pthreads_locking_callback(int mode, int type, char *file, int line){
    if(mode & CRYPTO_LOCK){
        pthread_mutex_lock(&(lock_cs[type]));
        lock_count[type]++;
    } else {
        pthread_mutex_unlock(&(lock_cs[type]));
    }
}

unsigned long pthreads_thread_id(void){
    unsigned long ret;
    ret = (unsigned long)pthread_self();
    return ret;
}
#endif 

void thread_setup(void){
    int i;

    pthread_mutex_init(&stat_mutex, NULL);
    pthread_mutex_init(&err_mutex, NULL);

#ifdef USE_SSL
    lock_cs = OPENSSL_malloc(CRYPTO_num_locks() * sizeof(pthread_mutex_t));
    lock_count = OPENSSL_malloc(CRYPTO_num_locks() * sizeof(long));
    for(i = 0; i < CRYPTO_num_locks(); i++){
        lock_count[i] = 0;
        pthread_mutex_init(&(lock_cs[i]), NULL);
    }
    CRYPTO_set_id_callback((unsigned long (*)())pthreads_thread_id);
    CRYPTO_set_locking_callback((void(*)())pthreads_locking_callback);
#endif
}

void thread_cleanup(void){
    int i;

    pthread_mutex_destroy(&stat_mutex);
    pthread_mutex_destroy(&err_mutex);
#ifdef USE_SSL
    CRYPTO_set_locking_callback(NULL);
    for(i = 0; i < CRYPTO_num_locks(); i++){
        pthread_mutex_destroy(&(lock_cs[i]));
    }
    OPENSSL_free(lock_cs);
    OPENSSL_free(lock_count);
#endif
}


/* --------------------------------------------------------- */

/* run the tests */

void *testMain(void *arg){
	_cpu = *(int *)arg;
	int i;
	apr_int16_t rv;
	apr_status_t status;
	_concurrency = concurrency / _num_cpus;
	if(_cpu < (concurrency % _num_cpus))
		_concurrency++;

	_requests = requests / _num_cpus;
	if(_cpu < (requests % _num_cpus))
		_requests++;

	if (isproxy) {
        connecthost = apr_pstrdup(cntxt, proxyhost);
        _connectport = proxyport;
    }
    else {
        connecthost = apr_pstrdup(cntxt, hostname);
        _connectport = port;
		if(num_ports != 1){
			_connectport += (_cpu % num_ports);
		}
    }

    /* This only needs to be done once */
    if ((rv = apr_sockaddr_info_get(&_destsa, connecthost, APR_UNSPEC, _connectport, 0, cntxt))
       != APR_SUCCESS) {
        char buf[120];
        apr_snprintf(buf, sizeof(buf),
                 "apr_sockaddr_info_get() for %s", connecthost);
        apr_err(buf, rv);
    }

	printf("CPU%d connecting to port %d\n", _cpu, _connectport);
#ifdef HAVE_MTCP
    mtcp_core_affinitize(_cpu);
	g_mctx[_cpu] = mtcp_create_context(_cpu);
	if (g_mctx[_cpu] == NULL){
		perror("mtcp_create_context");
		return NULL;
	}
	mtcp_init_rss(g_mctx[_cpu], INADDR_ANY, 1, _destsa->sa.sin.sin_addr.s_addr, _destsa->sa.sin.sin_port);
#else
	core_affinitize(_cpu);
#endif

	apr_pool_create(&_cntxt, cntxt);
	readbits = NULL;
	if ((status = apr_pollset_create(&readbits, _concurrency*4, _cntxt, APR_POLLSET_THREADSAFE)) != APR_SUCCESS) {
		apr_err("apr_pollset_create failed", status);
	}

	_lasttime = apr_time_now();
    con = calloc(_concurrency, sizeof(struct connection));
	_stats = calloc(_requests, sizeof(struct data));

	/* initialise lots of requests */
	for (i = 0; i < _concurrency; i++) {
        con[i].socknum = i;
		start_connect(&con[i]);
    }

    do {
        apr_int32_t n;
        const apr_pollfd_t *pollresults;

        n = _concurrency;
        do {
			status = apr_pollset_poll(readbits, aprtimeout, &n, &pollresults);
		} while (APR_STATUS_IS_EINTR(status));

        if (status != APR_SUCCESS)
            apr_err("apr_poll", status);

        if (!n) {
            err("\nServer timed out\n\n");
        }

        for (i = 0; i < n; i++) {
			const apr_pollfd_t *next_fd = &(pollresults[i]);
            struct connection *c;

            c = next_fd->client_data;

            /*
             * If the connection isn't connected how can we check it?
             */
            if (c->state == STATE_UNCONNECTED){
                continue;
			}

            rv = next_fd->rtnevents;

#ifdef USE_SSL
            if (c->state == STATE_CONNECTED && c->ssl && SSL_in_init(c->ssl)) {
                ssl_proceed_handshake(c);
                continue;
            }
#endif

            /*
             * Notes: APR_POLLHUP is set after FIN is received on some
             * systems, so treat that like APR_POLLIN so that we try to read
             * again.
             *
             * Some systems return APR_POLLERR with APR_POLLHUP.  We need to
             * call read_connection() for APR_POLLHUP, so check for
             * APR_POLLHUP first so that a closed connection isn't treated
             * like an I/O error.  If it is, we never figure out that the
             * connection is done and we loop here endlessly calling
             * apr_poll().
             */

			if ((rv & APR_POLLIN) || (rv & APR_POLLPRI) || (rv & APR_POLLHUP))
                read_connection(c);
            if ((rv & APR_POLLERR) || (rv & APR_POLLNVAL)) {
				pthread_mutex_lock(&err_mutex);
				bad++;
                err_except++;
				pthread_mutex_unlock(&err_mutex);
                start_connect(c);
                continue;
            }
            if (rv & APR_POLLOUT) {
                if (c->state == STATE_CONNECTING) {
					apr_pollfd_t remove_pollfd;
                    rv = apr_socket_connect(c->aprsock, _destsa);
					remove_pollfd.desc_type = APR_POLL_SOCKET;
                    remove_pollfd.desc.s = c->aprsock;
					apr_pollset_remove(readbits, &remove_pollfd);
					if (rv != APR_SUCCESS) {
                        if (bad> 100) {
                            fprintf(stderr,
                                    "\nTest aborted after 100 failures\n\n");
                            apr_err("apr_socket_connect()", rv);
                        }
						pthread_mutex_lock(&err_mutex);
						bad++;
						err_conn++;
						pthread_mutex_unlock(&err_mutex);
                        c->state = STATE_UNCONNECTED;
                        start_connect(c);
                        continue;
                    }
                    else {
                        c->state = STATE_CONNECTED;
						_started++;
#ifdef USE_SSL
						if (c->ssl)
                            ssl_proceed_handshake(c);
                        else
#endif
						write_request(c);
                    }
                }
                else {
					write_request(c);
                }
            }

            /*
             * When using a select based poll every time we check the bits
             * are reset. In 1.3's ab we copied the FD_SET's each time
             * through, but here we're going to check the state and if the
             * connection is in STATE_READ or STATE_CONNECTING we'll add the
             * socket back in as APR_POLLIN.
             */
			if (c->state == STATE_READ) {
				apr_pollfd_t new_pollfd;
                new_pollfd.desc_type = APR_POLL_SOCKET;
                new_pollfd.reqevents = APR_POLLIN;
                new_pollfd.desc.s = c->aprsock;
                new_pollfd.client_data = c;
                apr_pollset_add(readbits, &new_pollfd);
            }
        }

	} while (_lasttime < stoptime && _done < _requests);

	pthread_mutex_lock(&stat_mutex);
	for(i = 0; i < _done; i++){
		memcpy(&stats[done+i], &_stats[i], sizeof(struct data));
	}
	totalread += _totalread;    
	totalbread += _totalbread;   
	totalposted += _totalposted; 
	started += _started;          
	done += _done;              
	doneka += _doneka;          
	good += _good;
	lasttime = _lasttime;
	doclen = _doclen;

	pthread_mutex_unlock(&stat_mutex);

#ifdef HAVE_MTCP
	mtcp_destroy_context(g_mctx[_cpu]);
#endif
	return NULL;
}


static void test(void)
{
    int i;
    apr_int16_t rv;
    apr_status_t status;
    int snprintf_res = 0;
#ifdef NOT_ASCII
    apr_size_t inbytes_left, outbytes_left;
#endif
#ifdef HAVE_MTCP
    mtcp_init("config/mtcp.conf");
#endif
    if (!use_html) {
        printf("Benchmarking %s ", hostname);
    if (isproxy)
        printf("[through %s:%d] ", proxyhost, proxyport);
    	printf("(be patient)%s", (heartbeatres ? "\n" : "...\n"));
    	fflush(stdout);
    }

    stats = calloc(requests, sizeof(struct data));

    /* add default headers if necessary */
    if (!opt_host) {
        /* Host: header not overridden, add default value to hdrs */
        hdrs = apr_pstrcat(cntxt, hdrs, "Host: ", host_field, colonhost, "\r\n", NULL);
    }
    else {
        /* Header overridden, no need to add, as it is already in hdrs */
    }

    if (!opt_useragent) {
        /* User-Agent: header not overridden, add default value to hdrs */
        hdrs = apr_pstrcat(cntxt, hdrs, "User-Agent: ApacheBench/", AP_AB_BASEREVISION, "\r\n", NULL);
    }
    else {
        /* Header overridden, no need to add, as it is already in hdrs */
    }

    if (!opt_accept) {
        /* Accept: header not overridden, add default value to hdrs */
        hdrs = apr_pstrcat(cntxt, hdrs, "Accept: */*\r\n", NULL);
    }
    else {
        /* Header overridden, no need to add, as it is already in hdrs */
    }

    /* setup request */
    if (posting <= 0) {
        snprintf_res = apr_snprintf(request, sizeof(_request),
            "%s %s HTTP/1.0\r\n"
            "%s" "%s" "%s"
            "%s" "\r\n",
            (posting == 0) ? "GET" : "HEAD",
            (isproxy) ? fullurl : path,
            keepalive ? "Connection: Keep-Alive\r\n" : "",
            cookie, auth, hdrs);
    }
    else {
        snprintf_res = apr_snprintf(request,  sizeof(_request),
            "%s %s HTTP/1.0\r\n"
            "%s" "%s" "%s"
            "Content-length: %" APR_SIZE_T_FMT "\r\n"
            "Content-type: %s\r\n"
            "%s"
            "\r\n",
            (posting == 1) ? "POST" : "PUT",
            (isproxy) ? fullurl : path,
            keepalive ? "Connection: Keep-Alive\r\n" : "",
            cookie, auth,
            postlen,
            (content_type[0]) ? content_type : "text/plain", hdrs);
    }
    if (snprintf_res >= sizeof(_request)) {
        err("Request too long\n");
    }

    if (verbosity >= 2)
        printf("INFO: %s header == \n---\n%s\n---\n", 
                (posting == 2) ? "PUT" : "POST", request);

    reqlen = strlen(request);

    /*
     * Combine headers and (optional) post file into one contineous buffer
     */
    if (posting >= 1) {
        char *buff = malloc(postlen + reqlen + 1);
        if (!buff) {
            fprintf(stderr, "error creating request buffer: out of memory\n");
            return;
        }
        strcpy(buff, request);
        memcpy(buff + reqlen, postdata, postlen);
        request = buff;
    }

#ifdef NOT_ASCII
    inbytes_left = outbytes_left = reqlen;
    status = apr_xlate_conv_buffer(to_ascii, request, &inbytes_left,
                   request, &outbytes_left);
    if (status || inbytes_left || outbytes_left) {
        fprintf(stderr, "only simple translation is supported (%d/%"
                        APR_SIZE_T_FMT "/%" APR_SIZE_T_FMT ")\n",
                        status, inbytes_left, outbytes_left);
        exit(1);
    }
#endif              /* NOT_ASCII */
    /* ok - lets start */
    start = lasttime = apr_time_now();
    stoptime = tlimit ? (start + apr_time_from_sec(tlimit)) : AB_MAX;

#ifdef SIGINT 
    /* Output the results if the user terminates the run early. */
#ifdef HAVE_MTCP
	mtcp_register_signal(SIGINT, output_results);
#else
    apr_signal(SIGINT, output_results);
#endif
#endif

    thread_setup();

	/* Allocate connections to each thread
 	* and create threads*/
	for(i = 0; i < _num_cpus; i++){
		thread_cpu[i] = i;
		if(pthread_create(&app_thread[i], NULL, testMain, (void *)&thread_cpu[i])){
			perror("pthread_create");
			exit(-1);
		}
	}

	for(i = 0; i < _num_cpus; i++){
		pthread_join(app_thread[i], NULL);
	}	

    thread_cleanup();

	if (heartbeatres)
        fprintf(stderr, "Finished %d requests\n", done);
    else
        printf("..done\n");

    if (use_html)
        output_html_results();
    else
        output_results(0);

#ifdef HAVE_MTCP
	mtcp_destroy();
#endif

}

